// 이 함수는 그대로 두세요
async function get(url) {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error('불러오지 못했습니다 (' + res.status + ')');
  }
  return res.json();
}

async function main() {
  const start = Date.now();

  const courses = await get('/api/courses');
  const notices = await get('/api/notices');
  const me = await get('/api/me');

  console.log('코스', courses.length + '개 · 공지', notices.length + '개 ·', me.name);
  console.log('순서대로 기다린 시간:', Date.now() - start, 'ms');
}

main();

