// 이 함수는 그대로 두세요
async function get(url) {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error('불러오지 못했습니다 (' + res.status + ')');
  }
  return res.json();
}

async function dashboard(meUrl) {
  const [courses, notices, me] = await Promise.all([
    get('/api/courses'),
    get('/api/notices'),
    get(meUrl),
  ]);

  const enrolled = await get('/api/enrolled/' + me.id);

  return {
    courses: courses.length,
    notices: notices.length,
    name: me.name,
    enrolled: enrolled.length,
  };
}
